async function init() {
  await loadStatus();
  await loadConfig();
  await loadPrompts();
  fillSessionForm();
  refreshRunSummary();
  loadCurrentJob();
  // If the project has no model configured yet, land on Setup; otherwise it is
  // already the default view.
  setInterval(loadStatus, 60000);
}

init();
